import os
from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parent
sdk = os.environ.get("JAVAFX_LIB")
if not sdk or not (Path(sdk) / "javafx.graphics.jar").is_file():
    raise SystemExit("Unavailable: set JAVAFX_LIB to the JavaFX 25 SDK lib directory.")
with tempfile.TemporaryDirectory() as output:
    result = subprocess.run([
        "javac", "--release", "25", "--module-path", sdk,
        "--add-modules", "javafx.graphics", "-d", output,
        *map(str, (root / "src/main/java").rglob("*.java")),
    ], check=False)
    raise SystemExit(result.returncode)
package resolveit.ui;

import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public final class Navigator {
    private final Stage stage;
    private View currentView;

    public Navigator(Stage stage) {
        this.stage = stage;
    }

    public void show(View view) {
        if (currentView != null) {
            currentView.dispose();
        }
        Parent root = view.root();
        Scene scene = new Scene(root, 1120, 720);
        scene.getStylesheets().add(Navigator.class.getResource("/styles/app.css").toExternalForm());
        stage.setScene(scene);
        currentView = view;
        stage.show();
        currentView.onShown();
    }
}
package resolveit.ui;

import javafx.scene.Parent;

public interface View {
    Parent root();
    void onShown();
    void dispose();
}


